statement:
A global function `rand7()` is available; each call returns an integer from `1` to `7`, every value equally likely and independent of earlier calls. Write `rand10()`, which must return an integer from `1` to `10` with every value equally likely, independently on each call. Its only source of randomness may be `rand7()`: do not use `Math.random` or any other random generator.

Each test case is one number `n`, the number of times the judge calls `rand10()`. It is not passed to your function (the `n` parameter is `undefined`); `rand10()` is simply called `n` times and the answer is the list of its results in order. Because many lists are correct, the judge accepts any list that fits:

- it has `n` integers, each from `1` to `10`;
- `rand7` is driven by a fixed seed, and when `n >= 2000` the counts of single results and of consecutive pairs must pass chi-square tests for uniformity;
- `rand7` must be called often enough to make `n` uniform results possible: `7^calls >= 10^n`.

checker:
function check(input, actual, expected) {
  const [n] = input;
  if (!Array.isArray(actual) || actual.length !== n) return false;
  if (!actual.every(v => Number.isInteger(v) && v >= 1 && v <= 10)) return false;
  // Short lists cannot be told apart from random ones; long ones must pass two chi-square tests.
  if (n < 2000) return true;
  const single = new Array(10).fill(0);
  for (const v of actual) single[v - 1]++;
  const pairs = new Array(100).fill(0);
  for (let i = 0; i + 1 < n; i += 2) pairs[(actual[i] - 1) * 10 + actual[i + 1] - 1]++;
  const chiSquare = (counts, total) => {
    const each = total / counts.length;
    return counts.reduce((sum, c) => sum + (c - each) ** 2 / each, 0);
  };
  // Thresholds with a false-alarm chance of about 1e-7 for 9 and 99 degrees of freedom.
  return chiSquare(single, n) < 50 && chiSquare(pairs, Math.floor(n / 2)) < 200;
}

validator:
function validate([n]) {
  if (!Number.isInteger(n) || n < 1 || n > 100000) return 'n is a whole number from 1 to 10^5.';
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [n] = input;
  // rand7 comes from a seeded generator (mulberry32), so every run is repeatable.
  let state = (0x2545f491 ^ Math.imul(n, 0x9e3779b1)) >>> 0;
  let calls = 0;
  globalThis.rand7 = () => {
    calls++;
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return 1 + Math.floor((((t ^ (t >>> 14)) >>> 0) / 4294967296) * 7);
  };
  const random = Math.random;
  Math.random = () => { throw new Error('Math.random is not allowed: build rand10 from rand7() only.'); };
  const results = [];
  try {
    for (let i = 0; i < n; i++) results.push(solve());
  } finally {
    Math.random = random;
  }
  if (calls * Math.log(7) + 1e-9 < n * Math.log(10)) throw new Error(`rand7 was called ${calls} times for ${n} results; uniform results need 7^calls >= 10^n.`);
  return results;
}

